  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <header class="site-header">
      <div class="page-shell">
        <a class="brand" href="#" aria-label="Acme Support home">
          <span class="brand-mark" aria-hidden="true">A</span>
          <span>Acme Support</span>
        </a>
      </div>
    </header>

    <main id="maincontent" class="page-shell" tabindex="-1"></main>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          validate(value) {
            return value.trim() ? "" : "Error: Enter your full name.";
          },
        },
        {
          id: "email",
          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          validate(value) {
            const trimmed = value.trim();
            if (!trimmed) {
              return "Error: Enter your email address.";
            }

            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
              ? ""
              : "Error: Enter a valid email address like name@example.com.";
          },
        },
        {
          id: "phone",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          helperText: "Use digits, spaces, dashes, or parentheses, such as (555) 123-4567.",
          validate(value) {
            const trimmed = value.trim();
            if (!trimmed) {
              return "";
            }

            return /^\+?[\d\s().-]{7,20}$/.test(trimmed)
              ? ""
              : "Error: Enter a phone number using digits, spaces, dashes, or parentheses.";
          },
        },
      ];

      function Field({ id, name, label, type, autocomplete, required, helperText }) {
        const helperId = `${id}-help`;
        const errorId = `${id}-error`;
        const describedBy = [helperText ? helperId : "", errorId].filter(Boolean).join(" ");
        const requiredMarker = required
          ? ' <span class="required-marker" aria-hidden="true">*</span>'
          : " <span class=\"helper\">(optional)</span>";

        return `
          <div class="form-field">
            <label for="${id}">${label}${requiredMarker}</label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              autocomplete="${autocomplete}"
              ${required ? "required" : ""}
              aria-describedby="${describedBy}"
            >
            ${helperText ? `<p id="${helperId}" class="helper">${helperText}</p>` : ""}
            <p id="${errorId}" class="error" aria-live="polite"></p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="support-layout" aria-labelledby="support-heading">
            <div>
              <p class="eyebrow">Support</p>
              <h1 id="support-heading">How can we help?</h1>
              <p class="lede">
                Tell us how to reach you and our product support team will follow up with
                clear next steps.
              </p>
            </div>

            <div class="contact-card">
              <div class="form-header">
                <h2>Contact support</h2>
                <p class="required-note">
                  Fields marked with <span class="required-marker" aria-hidden="true">*</span>
                  are required.
                </p>
              </div>

              <form id="support-form" novalidate>
                ${fields.map(Field).join("")}
                <button type="submit">Send request</button>
                <p id="form-status" class="status-message" aria-live="polite"></p>
              </form>
            </div>
          </section>
        `;
      }

      function setFieldError(input, message) {
        const error = document.getElementById(`${input.id}-error`);
        if (!error) {
          return;
        }

        error.textContent = message;
        if (message) {
          input.setAttribute("aria-invalid", "true");
        } else {
          input.removeAttribute("aria-invalid");
        }
      }

      function validateInput(input) {
        const field = fields.find((item) => item.id === input.id);
        if (!field) {
          return true;
        }

        const message = field.validate(input.value);
        setFieldError(input, message);
        return !message;
      }

      function attachFormBehavior() {
        const form = document.getElementById("support-form");
        const status = document.getElementById("form-status");
        const inputs = Array.from(form.querySelectorAll("input"));

        inputs.forEach((input) => {
          input.addEventListener("blur", () => validateInput(input));
          input.addEventListener("input", () => {
            status.textContent = "";
            if (input.getAttribute("aria-invalid") === "true") {
              validateInput(input);
            }
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          status.textContent = "";

          const firstInvalid = inputs.find((input) => !validateInput(input));
          if (firstInvalid) {
            firstInvalid.focus();
            return;
          }

          form.reset();
          inputs.forEach((input) => setFieldError(input, ""));
          status.textContent = "Your support request is ready to send.";
        });
      }

      document.getElementById("maincontent").innerHTML = ContactForm();
      attachFormBehavior();
    </script>
